// --- Callbacks ---
static void start_btn_cb(lv_event_t * e) { ESP_LOGI(TAG, "Motor Start Initiated"); }
static void stop_btn_cb(lv_event_t * e)  { ESP_LOGI(TAG, "Motor Emergency Stop!"); }

static void create_main_ui(lv_display_t *disp) {
    lv_obj_t *scr = lv_display_get_screen_active(disp);

    lv_obj_t * btn_stop = lv_button_create(scr);
    lv_obj_set_size(btn_stop, 120, 60);
    lv_obj_align(btn_stop, LV_ALIGN_CENTER, 0, 40);
    lv_obj_t * lbl_stop = lv_label_create(btn_stop);
    lv_label_set_text(lbl_stop, LV_SYMBOL_STOP " STOP");
    lv_obj_center(lbl_stop);
    lv_obj_add_event_cb(btn_stop, stop_btn_cb, LV_EVENT_CLICKED, NULL);
}

static void splash_timer_cb(lv_timer_t * timer) {
    lv_display_t *disp = (lv_display_t *)lv_timer_get_user_data(timer);
    lv_obj_delete(splash_screen);
    create_main_ui(disp);
}

// --- LVGL v9 Porting Callbacks ---
static void lvgl_flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map) {
    esp_lcd_panel_handle_t panel_handle = (esp_lcd_panel_handle_t)lv_display_get_user_data(disp);
    int x1 = area->x1;
    int y1 = area->y1;
    int x2 = area->x2;
    int y2 = area->y2;
    esp_lcd_panel_draw_bitmap(panel_handle, x1, y1, x2 + 1, y2 + 1, px_map);
    lv_display_flush_ready(disp);
}

static void lvgl_touch_cb(lv_indev_t *indev, lv_indev_data_t *data) {
    uint16_t x[1], y[1], strength[1];
    uint8_t count = 0;
    esp_lcd_touch_read_data(tp);
    if (esp_lcd_touch_get_coordinates(tp, x, y, strength, &count, 1)) {
        data->point.x = x[0];
        data->point.y = y[0];
        data->state = LV_INDEV_STATE_PRESSED;
    } else {
        data->state = LV_INDEV_STATE_RELEASED;
    }
}

static void lvgl_tick_task(void *arg) { lv_tick_inc(5); }

void app_main(void) {
    // 1. SPI Init
    spi_bus_config_t buscfg = {
        .sclk_io_num = PIN_NUM_SCLK, .mosi_io_num = PIN_NUM_MOSI, .miso_io_num = PIN_NUM_MISO,
        .quadwp_io_num = -1, .quadhd_io_num = -1, .max_transfer_sz = LCD_H_RES * 100 * 2
    };
    ESP_ERROR_CHECK(spi_bus_initialize(LCD_HOST, &buscfg, SPI_DMA_CH_AUTO));

    // 2. LCD IO & Panel
    esp_lcd_panel_io_handle_t io_handle = NULL;
    esp_lcd_panel_io_spi_config_t io_config = {
        .dc_gpio_num = PIN_NUM_LCD_DC, .cs_gpio_num = PIN_NUM_LCD_CS,
        .pclk_hz = 40 * 1000 * 1000, .lcd_cmd_bits = 8, .lcd_param_bits = 8, .spi_mode = 0, .trans_queue_depth = 10,
    };
    ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi((esp_lcd_spi_bus_handle_t)LCD_HOST, &io_config, &io_handle));

    esp_lcd_panel_handle_t panel_handle = NULL;
    esp_lcd_panel_dev_config_t panel_config = {
        .reset_gpio_num = PIN_NUM_LCD_RST, .rgb_ele_order = LCD_RGB_ELEMENT_ORDER_BGR, .bits_per_pixel = 16,
    };
    ESP_ERROR_CHECK(esp_lcd_new_panel_ili9341(io_handle, &panel_config, &panel_handle));
    esp_lcd_panel_reset(panel_handle);
    esp_lcd_panel_init(panel_handle);
    esp_lcd_panel_swap_xy(panel_handle, true);
    esp_lcd_panel_mirror(panel_handle, true, false);
    esp_lcd_panel_disp_on_off(panel_handle, true);

    // 3. Touch Init
    esp_lcd_panel_io_handle_t tp_io_handle = NULL;
    esp_lcd_panel_io_spi_config_t tp_io_config = ESP_LCD_TOUCH_IO_SPI_XPT2046_CONFIG(PIN_NUM_TOUCH_CS);
    ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi((esp_lcd_spi_bus_handle_t)LCD_HOST, &tp_io_config, &tp_io_handle));
    esp_lcd_touch_config_t tp_cfg = {
        .x_max = LCD_H_RES, .y_max = LCD_V_RES, .rst_gpio_num = -1, .int_gpio_num = -1,
        .flags = { .swap_xy = 1, .mirror_x = 1, .mirror_y = 0 },
    };
    ESP_ERROR_CHECK(esp_lcd_touch_new_spi_xpt2046(tp_io_handle, &tp_cfg, &tp));

    // 4. LVGL v9 Init
    lv_init();
    lv_display_t *disp = lv_display_create(LCD_H_RES, LCD_V_RES);
    lv_display_set_user_data(disp, panel_handle);
    lv_display_set_flush_cb(disp, lvgl_flush_cb);

    uint8_t *buf1 = heap_caps_malloc(LCD_DRAW_BUFF_SIZE * 2, MALLOC_CAP_DMA);
    lv_display_set_buffers(disp, buf1, NULL, LCD_DRAW_BUFF_SIZE * 2, LV_DISPLAY_RENDER_MODE_PARTIAL);

    // 5. Input Init
    lv_indev_t *indev = lv_indev_create();
    lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
    lv_indev_set_read_cb(indev, lvgl_touch_cb);

    // 6. Ticks and Splash
    const esp_timer_create_args_t tick_timer_args = { .callback = &lvgl_tick_task, .name = "lv_tick" };
    esp_timer_handle_t tick_timer = NULL;
    esp_timer_create(&tick_timer_args, &tick_timer);
    esp_timer_start_periodic(tick_timer, 5000);

    splash_screen = lv_obj_create(lv_display_get_screen_active(disp));
    lv_obj_set_size(splash_screen, LCD_H_RES, LCD_V_RES);
    lv_obj_t * img = lv_image_create(splash_screen);
    lv_image_set_src(img, &hackerfab_logo);
    lv_obj_center(img);
    lv_timer_t * t = lv_timer_create(splash_timer_cb, 3000, disp);

    while (1) {
        lv_timer_handler();
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}